// "box" — a SHAPE: it draws a primitive on the picture lane it is wired to, and takes no picture
// in. The folder it sits in (`_modules/shapes/`) is what says so.
//
// The geometry is `params:` rather than fields, and that is the whole point of a shape being a
// module: a param is what a curve can drive, so this rectangle can be made to move.
// See apps/k7-daw-frontend/packages/song-video/docs/shapes.md.
type("shape")
shape("square")
color("#e2b53acc")
params({ x: 448, y: 220, w: 384, h: 280 })

source("clips/kick.wav")
from(0)
to(0.1)

// The Tracktion built-in compressor, given a face: `ui.k7x` beside this file lays out the
// knobs and a screen, and `widgets.js` draws the screen — what is being compressed, live.
extends("@engine/compressor")

// compressor — what its lcdscreen draws: the transfer curve on the left, and on the right the
// last seconds of signal, input against output with the makeup gain taken back out, so the
// lit band between them is exactly what the compressor removed. The curve is Tracktion's own
// law (linear domain: above T, out = T + (in - T) * ratio, then the output gain); the band and
// the GR readout are MEASURED off the engine's taps either side of the plugin, never simulated.

const FLOOR = -48; // dB at the bottom of every scale
const db = (x) => (x > 1e-6 ? 20 * Math.log10(x) : -120);
const lin = (d) => 10 ** (d / 20);

// The compressor's static curve, output level for an input level, both linear.
const curve = (x, t, ratio, makeup) =>
  (x <= t ? x : t + (x - t) * ratio) * makeup;

// The loudest point of `a` between two indices — the peak a pixel column stands for.
function peak(a, from, to) {
  let m = 0;
  for (let i = Math.max(0, from); i < Math.min(a.length, to); i++)
    if (a[i] > m) m = a[i];
  return m;
}

export default {
  screen(lcd) {
    const { ctx, width: W, height: H, params, input, output, color } = lcd;
    const t = params.Threshold ?? 0.501;
    const ratio = params.Ratio ?? 0.5;
    const makeupDb = params["Output gain"] ?? 0;
    const makeup = lin(makeupDb);
    ctx.font = "8px ui-monospace, monospace";
    ctx.textBaseline = "top";

    // Gain reduction NOW, off the last ~50 ms of both taps, with meter ballistics kept in `state`.
    const n = Math.min(input.length, output.length);
    const inNow = peak(input, input.length - 8, input.length);
    const outNow = peak(output, output.length - 8, output.length);
    const grRaw =
      n && inNow > 1e-4 ? Math.min(0, db(outNow) - makeupDb - db(inNow)) : 0;
    const s = lcd.state;
    s.gr = grRaw < (s.gr ?? 0) ? grRaw : (s.gr ?? 0) * 0.85 + grRaw * 0.15;

    // Header: the settings as a person reads them, then the one live number.
    const ratioText = ratio > 0.001 ? `${(1 / ratio).toFixed(1)}:1` : "inf:1";
    ctx.fillStyle = color.dim;
    ctx.fillText(`T ${db(t).toFixed(1)}dB  ${ratioText}`, 2, 1);
    ctx.fillStyle = s.gr < -0.5 ? color.glow : color.ink;
    const grText = n ? `GR ${s.gr.toFixed(1)}dB` : "GR --";
    ctx.fillText(grText, W - ctx.measureText(grText).width - 2, 1);

    // --- the transfer curve, a square on the left ---------------------------------------------
    const top = 11;
    const S = Math.max(10, H - top - 2);
    const toX = (d) => 2 + ((d - FLOOR) / -FLOOR) * S;
    const toY = (d) => top + (1 - (d - FLOOR) / -FLOOR) * S;
    ctx.save();
    ctx.beginPath();
    ctx.rect(2, top, S, S);
    ctx.clip();
    ctx.strokeStyle = color.dim;
    ctx.lineWidth = 1;
    ctx.strokeRect(2.5, top + 0.5, S - 1, S - 1);
    // Unity, dashed: how far the curve bends under it is the compression.
    ctx.setLineDash([2, 2]);
    ctx.beginPath();
    ctx.moveTo(toX(FLOOR), toY(FLOOR));
    ctx.lineTo(toX(0), toY(0));
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.strokeStyle = color.ink;
    ctx.lineWidth = 1.25;
    ctx.beginPath();
    for (let px = 0; px <= S; px++) {
      const d = FLOOR + (px / S) * -FLOOR;
      const y = toY(db(curve(lin(d), t, ratio, makeup)));
      if (px === 0) ctx.moveTo(2 + px, y);
      else ctx.lineTo(2 + px, y);
    }
    ctx.stroke();
    // Where the signal sits on the curve right now.
    if (n && inNow > lin(FLOOR)) {
      const d = db(inNow);
      ctx.fillStyle = color.glow;
      ctx.beginPath();
      ctx.arc(toX(d), toY(db(curve(inNow, t, ratio, makeup))), 2.2, 0, 7);
      ctx.fill();
    }
    ctx.restore();

    // --- the history, right of the square -----------------------------------------------------
    const x0 = S + 7;
    const w = W - x0 - 2;
    if (w < 8) return;
    const yOf = (d) =>
      top + (1 - (Math.max(FLOOR, Math.min(0, d)) - FLOOR) / -FLOOR) * S;
    const bottom = top + S;
    ctx.strokeStyle = color.dim;
    ctx.strokeRect(x0 + 0.5, top + 0.5, w - 1, S - 1);
    // The threshold, where compression starts.
    ctx.setLineDash([2, 2]);
    ctx.beginPath();
    ctx.moveTo(x0, yOf(db(t)) + 0.5);
    ctx.lineTo(x0 + w, yOf(db(t)) + 0.5);
    ctx.stroke();
    ctx.setLineDash([]);
    if (!n) {
      ctx.fillStyle = color.dim;
      ctx.fillText("no signal", x0 + 4, top + S / 2 - 4);
      return;
    }
    // One column per pixel, newest on the right; both taps end NOW, so they are aligned from the end.
    const per = Math.max(1, Math.floor(n / w));
    for (let c = 0; c < w; c++) {
      const back = (w - c) * per;
      const i = input.length - back;
      const o = output.length - back;
      if (i < 0 || o < 0) continue;
      const inDb = db(peak(input, i, i + per));
      const outDb = db(peak(output, o, o + per)) - makeupDb;
      const x = x0 + c;
      // What came in, faint…
      ctx.fillStyle = color.dim;
      ctx.fillRect(x, yOf(inDb), 1, bottom - yOf(inDb));
      // …what was taken off it, lit…
      if (inDb - outDb > 0.3) {
        ctx.fillStyle = color.glow;
        ctx.fillRect(x, yOf(inDb), 1, yOf(outDb) - yOf(inDb));
      }
      // …and what went on, as the line on top of what is left.
      ctx.fillStyle = color.ink;
      ctx.fillRect(x, yOf(outDb), 1, 1);
    }
  },
};

// Crossfade — the DSP as data, read by the song crate into the graph jsdsp.ts builds (docs/dsp-literal-plan.md).
// input(0) and input(1) index the ports module.k7x declares, in order: `a` then `b`.
params({
  Mix: { min: 0, max: 1, default: 0.5 },
})
graph([
  // Equal gain, not equal power: there is no sqrt among the primitives.
  output(aadd(amul(input(0), sub(1, "Mix")), amul(input(1), "Mix"))),
])

// The crossfade's DSP. The builder arrives as an ARGUMENT, so this file imports nothing at runtime — a song
// folder has no node_modules and should never need one (the `import type` is erased; see dspRunner.mjs).
//
// `input(0)` and `input(1)` index the ports module.k7x declares, in order: `a` then `b`. An index and not a
// name, because this graph is compiled to JSON the engine reads with no module.k7x in sight, and position is
// the one fact both documents can hold on their own.
//
// This is @studio/dsp's `crossfade()` graph, written out here: a module is a FOLDER you can copy, so it
// carries its own source rather than pointing at a shared library. packages/dsp/src/crossfade.test.ts holds
// the two to the same shape.

import type { GraphBuilder } from "@studio/dsp";

export default (g: GraphBuilder) => {
  const mix = g.param("Mix", { min: 0, max: 1, default: 0.5 });
  // Equal GAIN and not equal power: no sqrt among the primitives, so the centre dips a known ~3 dB.
  g.input(0).mul(mix.from(1)).add(g.input(1).mul(mix)).out();
};

// A module that declares its OWN ports, instead of taking the one audio input its type folder
// would have given it. That is the whole reason a crossfade was unsayable before: `audio/` means
// one in, one out, and a folder is not the right place to decide how many wires an effect takes.
//
// `mandatory: false` on `b`: wiring one side and leaving the other silent is a legitimate state,
// not a half-built chain. Drop this module into a chain on its own and it plays deck A alone.
//
// `plugin: {type: dsp}` says the sound comes from the `dsp.k7x` beside this file — one
// statement for both facts, so there is no `dsp:` field to keep in step with a plugin name.
plugin({ type: "dsp", name: "Crossfade" })
inputs([name("a").type("audio"), name("b").type("audio").mandatory(false)])
outputs([name("out").type("audio")])
params({
  // The graph's own parameter, by its display name — that is how a param finds its plugin
  // (see applyPluginParams). Centred: both decks at once, which is what makes the demo audible.
  Mix: 0.5,
})
// A two-input crossfade. Mix at 0 is deck A alone, at 1 deck B alone, at 0.5 both at half.
// (Was `docs:`. To say this on the GRAPH, wire this module into a node of `@meta/doc`.)

// A RACK instrument: a note -> audio sampler (type: "rack"), not a plugin. This module is the
// sampler and nothing more: the sounds — each a TAP, a MIDI note and the sample it fires — are
// written on the NODE that uses it (see rack-demo.k7/nodes/kit.k7x), so every node of this
// module can be a different kit. Samples live in a library's samples/ or a project's own.
type("rack")

// The Tracktion built-in 4OSC synth. It sits in instruments/, so it's a
// midi -> audio plugin with a mandatory MIDI input — both derived from the folder.
// `plugin.type` is the FORMAT: "internal" for a built-in, whose xmlTypeName goes in
// `name` (an external plugin uses type: "vst3" / "au" / … and name: its real name).
plugin({ type: "internal", name: "4osc" })
// The UI every module that extends this one draws inside its rectangle on the Chains
// graph. The extending module overrides one widget by restating it under the same id.
//
// The ranges are 4OSC's own. A built-in's params are in NATIVE units, not the 0..1
// an external plugin reports: "Filter Freq" is a 0..135 note-ish scale rather than
// Hz, and "Level" is dB. They have to be written down here — nothing reports a
// parameter's bounds at runtime, so an unranged control would be guessing.
ui({
  cols: 4,
  rows: 2,
  widgets: {
    title: { type: "label", col: 0, row: 0, colSpan: 2, text: "4OSC" },
    cutoff: {
      type: "knob",
      col: 0,
      row: 1,
      label: "Cutoff",
      bind: "Filter Freq",
      min: 0,
      max: 135.076232,
    },
    res: { type: "knob", col: 1, row: 1, label: "Res", bind: "Filter Resonance", min: 0, max: 100 },
    level: { type: "slider", col: 2, row: 1, label: "Level", bind: "Level", min: -100, max: 0 },
  },
})

// A module that extends the 4OSC (instruments/fourosc) with default params. Add a
// params: {…} here to tweak it, or a synth.vstpreset beside this file for opaque state
// (a UI edit writes that automatically).
//
// A module file is a flat struct of its own attributes, with no `package` clause —
// that keeps sibling modules in this folder from colliding on `name`.
//
// Two NODES use this module — nodes/lead.k7x and nodes/pad.k7x, which
// chains.k7x names "lead" and "pad". They live in the project's flat nodes/ folder
// rather than beside this file, and reach it through `extends`; whatever you change here
// reaches both.
extends("@workspace/instruments/fourosc")
// The lead 4OSC. Two saws detuned a few cents, a slow filter sweep on the way in.
//
// TODO: automate the filter cutoff instead of leaving it static; try a sub-oscillator an
// octave down.
//
// Was `docs:`/`todos:`, read by the Docs panel. To say this ON THE GRAPH instead, add a
// node of `@meta/doc` with a `content:` and wire this module into it.
// Automation. The hand-drawn `sweep` curve rides the filter cutoff — "Filter Freq"
// has a widget in the graph, so the curve's arrow lands on it. The bipolar `wobble`
// LFO detunes osc 1; "Osc1 Tune" has no widget, so its arrow points at the module
// with the param named instead.
automations([
  param("Filter Freq").curve("@meta/curves/sweep"),
  param("Osc1 Tune").curve("@meta/curves/wobble"),
])

// "glow" — a SHADER: picture in, picture out, and an optional audio input that drives it.
//
// The folder it sits in (`_modules/shaders/`) is what says so; nothing here names a plugin,
// because there is none. What this module DOES is the GLSL under `shaders/`, one folder per
// shader, and `shader:` below picks which of them runs.
//
// `P1`..`P4` are the four knobs every shader gets, 0..1, reaching the fragment as `uP1`..`uP4`.
// What each one means is the shader's business — read the comments in its fragment.glsl.
// See apps/k7-daw-frontend/packages/song-video/docs/shaders.md.
type("shader")
shader("pulse")
params({
  P1: 0.6, // pulse: how hard the sound lifts the picture
  P2: 0.35, // pulse: vignette
  P3: 0,
  P4: 0,
})

#version 300 es
// "pulse" — the picture brightens with the sound, inside a vignette.
//
// The simplest thing that shows the audio input actually arriving: wire a lane to this node's
// `audio` port and the frame breathes with it. With nothing wired, `uAudio` is 0 and this is a
// vignette and nothing else, which is a legitimate way to use it.
precision mediump float;

in vec2 vUV;

uniform sampler2D uTex;   // the picture coming in
uniform float uAudio;     // 0..1, the wired lane's live level (-60..0 dB)
uniform float uP1;        // how hard the sound lifts the picture
uniform float uP2;        // vignette depth

out vec4 outColor;

void main() {
  vec4 c = texture(uTex, vUV);

  // Lift, never cut: at uAudio 0 this is 1.0, so silence leaves the picture exactly as it came in.
  // A shader that darkened at rest would make every lane look wrong the moment you added it.
  float lift = 1.0 + uAudio * uP1 * 2.0;

  // Squared distance from the centre, doubled so the corners reach ~1 on a square frame.
  vec2 d = vUV - 0.5;
  float vig = 1.0 - uP2 * clamp(dot(d, d) * 2.0, 0.0, 1.0);

  // Alpha is passed straight through. The layer is composited OVER whatever is under it, so
  // writing 1.0 here would make a picture-in-picture punch a hole in the lane below it.
  outColor = vec4(c.rgb * lift * vig, c.a);
}

#version 300 es
// The vertex stage every full-target pass wants: `aUnit` is the unit quad the compositor binds,
// and a pass covers the whole of what it draws into — so this maps (0,0)..(1,1) onto clip space
// and hands the fragment the same 0..1 as its texture coordinate.
//
// It is a separate file, and duplicated per shader on purpose: a shader is the PAIR, and the day
// one wants to move its geometry it needs this file to itself rather than a shared one it would
// have to fork. See apps/k7-daw-frontend/packages/song-video/docs/shaders.md.
in vec2 aUnit;
out vec2 vUV;

void main() {
  vUV = aUnit;
  gl_Position = vec4(aUnit * 2.0 - 1.0, 0.0, 1.0);
}

#version 300 es
// "ripple" — rings running out from the centre, their depth driven by the sound.
//
// The second shader in this folder, and its job is to prove the dropdown: pick it instead of
// "pulse" and the same node, the same four knobs and the same audio cable do something else.
precision mediump float;

in vec2 vUV;

uniform sampler2D uTex;    // the picture coming in
uniform float uAudio;      // 0..1, the wired lane's live level
uniform float uTime;       // seconds — the TRANSPORT's position, not a clock of the renderer's
uniform vec2 uResolution;  // the viewport in px, for the aspect correction below
uniform float uP1;         // ring depth at full level
uniform float uP2;         // how many rings across the frame
uniform float uP3;         // how fast they travel

out vec4 outColor;

void main() {
  // Aspect-corrected, or the rings are ellipses on any frame that is not square. `uResolution` is
  // the VIEWPORT's — a layer's chain runs at viewport size whatever rect the lane occupies, which
  // is what keeps an effect looking the same on a picture-in-picture as on a full-frame lane.
  vec2 d = vUV - 0.5;
  d.x *= uResolution.x / max(uResolution.y, 1.0);
  float r = length(d);

  // 2..34 rings, and 0..2 rings per second outward. Both ends of each range are useful: the
  // bottom of `uP2` is a single slow swell, the top is a fine corduroy.
  float rings = 2.0 + uP2 * 32.0;
  float wave = sin(r * rings - uTime * uP3 * 2.0);

  // The displacement is along the radius, so the rings push the picture out and pull it back
  // rather than smearing it sideways. Guarded at the exact centre, where `d / r` is 0/0.
  float amount = wave * uAudio * uP1 * 0.05;
  vec2 dir = r > 0.0001 ? d / r : vec2(0.0);
  vec2 uv = clamp(vUV + dir * amount, 0.0, 1.0);

  outColor = texture(uTex, uv);
}

#version 300 es
// The same full-target quad "pulse" uses — see the note in its vertex.glsl for why each shader
// carries its own copy rather than sharing one.
in vec2 aUnit;
out vec2 vUV;

void main() {
  vUV = aUnit;
  gl_Position = vec4(aUnit * 2.0 - 1.0, 0.0, 1.0);
}

// The panel drawn inside this node's card on the graph.
//
// The dropdown binds `@shader` and says NOTHING about its entries: which shaders exist is a fact
// about the folder, and a list written here would be a copy of a directory going stale between
// saves. The graph fills it from what the loader found — the same arrangement `@base` has.
cols(4)
rows(2)
widgets({
  pick: { type: "dropdown", col: 0, row: 0, colSpan: 4, bind: "@shader" },
  p1: { type: "knob", col: 0, row: 1, bind: "P1", min: 0, max: 1, step: 0.01 },
  p2: { type: "knob", col: 1, row: 1, bind: "P2", min: 0, max: 1, step: 0.01 },
  p3: { type: "knob", col: 2, row: 1, bind: "P3", min: 0, max: 1, step: 0.01 },
  p4: { type: "knob", col: 3, row: 1, bind: "P4", min: 0, max: 1, step: 0.01 },
})

// "iris" — a SHADER meant for a fade's STRETCH: the shot is shown inside a circle that opens with
// its presence, so the same node opens a shot in on a `fade_in` and closes one out on a `fade_out`.
//
// Wired as an ordinary lane effect it does nothing, since `uPresence` is 1 outside a fade.
// See apps/k7-daw-frontend/packages/song-video/docs/transitions.md.
type("shader")
shader("iris")
params({
  P1: 0.15, // iris: how soft the circle's edge is
  P2: 0,
  P3: 0,
  P4: 0,
})

#version 300 es
// "iris" — the shot inside a circle whose radius follows `uPresence`: closed at 0, the whole
// frame at 1. Only the ALPHA changes, which is what lets the built-in `over` mix it with the shot
// underneath — see apps/k7-daw-frontend/packages/song-video/docs/transitions.md.
precision mediump float;

in vec2 vUV;

uniform sampler2D uTex;       // the shot coming in
uniform float uPresence;      // 0..1, how much of the shot is on screen
uniform vec2 uResolution;     // the viewport, so the circle stays round on a wide frame
uniform float uP1;            // edge softness

out vec4 outColor;

void main() {
  vec4 c = texture(uTex, vUV);
  // Distance from the centre in units of the frame's HEIGHT, so a 16:9 frame does not squash the circle.
  vec2 d = (vUV - 0.5) * vec2(uResolution.x / uResolution.y, 1.0);
  float soft = max(uP1 * 0.5, 0.001);
  // The radius reaches past the corner at presence 1, edge included, so a whole shot has no rim.
  float far = length(vec2(uResolution.x / uResolution.y, 1.0) * 0.5) + soft;
  float r = uPresence * far;
  outColor = vec4(c.rgb, c.a * (1.0 - smoothstep(r - soft, r, length(d))));
}

#version 300 es
// The vertex stage every full-target pass wants: `aUnit` is the unit quad the compositor binds,
// and a pass covers the whole of what it draws into — so this maps (0,0)..(1,1) onto clip space
// and hands the fragment the same 0..1 as its texture coordinate.
//
// It is a separate file, and duplicated per shader on purpose: a shader is the PAIR, and the day
// one wants to move its geometry it needs this file to itself rather than a shared one it would
// have to fork. See apps/k7-daw-frontend/packages/song-video/docs/shaders.md.
in vec2 aUnit;
out vec2 vUV;

void main() {
  vUV = aUnit;
  gl_Position = vec4(aUnit * 2.0 - 1.0, 0.0, 1.0);
}

// The panel drawn inside this node's card on the graph: the shader picker and the four knobs.
cols(4)
rows(2)
widgets({
  pick: { type: "dropdown", col: 0, row: 0, colSpan: 4, bind: "@shader" },
  p1: { type: "knob", col: 0, row: 1, bind: "P1", min: 0, max: 1, step: 0.01 },
  p2: { type: "knob", col: 1, row: 1, bind: "P2", min: 0, max: 1, step: 0.01 },
  p3: { type: "knob", col: 2, row: 1, bind: "P3", min: 0, max: 1, step: 0.01 },
  p4: { type: "knob", col: 3, row: 1, bind: "P4", min: 0, max: 1, step: 0.01 },
})

// "box" — a SHAPE: it draws a primitive on the picture lane it is wired to, and takes no picture
// in. The folder it sits in (`_modules/shapes/`) is what says so.
//
// The geometry is `params:` rather than fields, and that is the whole point of a shape being a
// module: a param is what a curve can drive, so this rectangle can be made to move.
// See apps/k7-daw-frontend/packages/song-video/docs/shapes.md.
type("shape")
shape("square")
color("#e2b53acc")
params({ x: 448, y: 220, w: 384, h: 280 })

// The Tracktion built-in compressor, given a face: `ui.k7x` beside this file lays out the
// knobs and a screen, and `widgets.js` draws the screen — what is being compressed, live.
extends("@engine/compressor")

// compressor — what its lcdscreen draws: the transfer curve on the left, and on the right the
// last seconds of signal, input against output with the makeup gain taken back out, so the
// lit band between them is exactly what the compressor removed. The curve is Tracktion's own
// law (linear domain: above T, out = T + (in - T) * ratio, then the output gain); the band and
// the GR readout are MEASURED off the engine's taps either side of the plugin, never simulated.

const FLOOR = -48; // dB at the bottom of every scale
const db = (x) => (x > 1e-6 ? 20 * Math.log10(x) : -120);
const lin = (d) => 10 ** (d / 20);

// The compressor's static curve, output level for an input level, both linear.
const curve = (x, t, ratio, makeup) =>
  (x <= t ? x : t + (x - t) * ratio) * makeup;

// The loudest point of `a` between two indices — the peak a pixel column stands for.
function peak(a, from, to) {
  let m = 0;
  for (let i = Math.max(0, from); i < Math.min(a.length, to); i++)
    if (a[i] > m) m = a[i];
  return m;
}

export default {
  screen(lcd) {
    const { ctx, width: W, height: H, params, input, output, color } = lcd;
    const t = params.Threshold ?? 0.501;
    const ratio = params.Ratio ?? 0.5;
    const makeupDb = params["Output gain"] ?? 0;
    const makeup = lin(makeupDb);
    ctx.font = "8px ui-monospace, monospace";
    ctx.textBaseline = "top";

    // Gain reduction NOW, off the last ~50 ms of both taps, with meter ballistics kept in `state`.
    const n = Math.min(input.length, output.length);
    const inNow = peak(input, input.length - 8, input.length);
    const outNow = peak(output, output.length - 8, output.length);
    const grRaw =
      n && inNow > 1e-4 ? Math.min(0, db(outNow) - makeupDb - db(inNow)) : 0;
    const s = lcd.state;
    s.gr = grRaw < (s.gr ?? 0) ? grRaw : (s.gr ?? 0) * 0.85 + grRaw * 0.15;

    // Header: the settings as a person reads them, then the one live number.
    const ratioText = ratio > 0.001 ? `${(1 / ratio).toFixed(1)}:1` : "inf:1";
    ctx.fillStyle = color.dim;
    ctx.fillText(`T ${db(t).toFixed(1)}dB  ${ratioText}`, 2, 1);
    ctx.fillStyle = s.gr < -0.5 ? color.glow : color.ink;
    const grText = n ? `GR ${s.gr.toFixed(1)}dB` : "GR --";
    ctx.fillText(grText, W - ctx.measureText(grText).width - 2, 1);

    // --- the transfer curve, a square on the left ---------------------------------------------
    const top = 11;
    const S = Math.max(10, H - top - 2);
    const toX = (d) => 2 + ((d - FLOOR) / -FLOOR) * S;
    const toY = (d) => top + (1 - (d - FLOOR) / -FLOOR) * S;
    ctx.save();
    ctx.beginPath();
    ctx.rect(2, top, S, S);
    ctx.clip();
    ctx.strokeStyle = color.dim;
    ctx.lineWidth = 1;
    ctx.strokeRect(2.5, top + 0.5, S - 1, S - 1);
    // Unity, dashed: how far the curve bends under it is the compression.
    ctx.setLineDash([2, 2]);
    ctx.beginPath();
    ctx.moveTo(toX(FLOOR), toY(FLOOR));
    ctx.lineTo(toX(0), toY(0));
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.strokeStyle = color.ink;
    ctx.lineWidth = 1.25;
    ctx.beginPath();
    for (let px = 0; px <= S; px++) {
      const d = FLOOR + (px / S) * -FLOOR;
      const y = toY(db(curve(lin(d), t, ratio, makeup)));
      if (px === 0) ctx.moveTo(2 + px, y);
      else ctx.lineTo(2 + px, y);
    }
    ctx.stroke();
    // Where the signal sits on the curve right now.
    if (n && inNow > lin(FLOOR)) {
      const d = db(inNow);
      ctx.fillStyle = color.glow;
      ctx.beginPath();
      ctx.arc(toX(d), toY(db(curve(inNow, t, ratio, makeup))), 2.2, 0, 7);
      ctx.fill();
    }
    ctx.restore();

    // --- the history, right of the square -----------------------------------------------------
    const x0 = S + 7;
    const w = W - x0 - 2;
    if (w < 8) return;
    const yOf = (d) =>
      top + (1 - (Math.max(FLOOR, Math.min(0, d)) - FLOOR) / -FLOOR) * S;
    const bottom = top + S;
    ctx.strokeStyle = color.dim;
    ctx.strokeRect(x0 + 0.5, top + 0.5, w - 1, S - 1);
    // The threshold, where compression starts.
    ctx.setLineDash([2, 2]);
    ctx.beginPath();
    ctx.moveTo(x0, yOf(db(t)) + 0.5);
    ctx.lineTo(x0 + w, yOf(db(t)) + 0.5);
    ctx.stroke();
    ctx.setLineDash([]);
    if (!n) {
      ctx.fillStyle = color.dim;
      ctx.fillText("no signal", x0 + 4, top + S / 2 - 4);
      return;
    }
    // One column per pixel, newest on the right; both taps end NOW, so they are aligned from the end.
    const per = Math.max(1, Math.floor(n / w));
    for (let c = 0; c < w; c++) {
      const back = (w - c) * per;
      const i = input.length - back;
      const o = output.length - back;
      if (i < 0 || o < 0) continue;
      const inDb = db(peak(input, i, i + per));
      const outDb = db(peak(output, o, o + per)) - makeupDb;
      const x = x0 + c;
      // What came in, faint…
      ctx.fillStyle = color.dim;
      ctx.fillRect(x, yOf(inDb), 1, bottom - yOf(inDb));
      // …what was taken off it, lit…
      if (inDb - outDb > 0.3) {
        ctx.fillStyle = color.glow;
        ctx.fillRect(x, yOf(inDb), 1, yOf(outDb) - yOf(inDb));
      }
      // …and what went on, as the line on top of what is left.
      ctx.fillStyle = color.ink;
      ctx.fillRect(x, yOf(outDb), 1, 1);
    }
  },
};

// Crossfade — the DSP as data, read by the song crate into the graph jsdsp.ts builds (docs/dsp-literal-plan.md).
// input(0) and input(1) index the ports module.k7x declares, in order: `a` then `b`.
params({
  Mix: { min: 0, max: 1, default: 0.5 },
})
graph([
  // Equal gain, not equal power: there is no sqrt among the primitives.
  output(aadd(amul(input(0), sub(1, "Mix")), amul(input(1), "Mix"))),
])

// The crossfade's DSP. The builder arrives as an ARGUMENT, so this file imports nothing at runtime — a song
// folder has no node_modules and should never need one (the `import type` is erased; see dspRunner.mjs).
//
// `input(0)` and `input(1)` index the ports module.k7x declares, in order: `a` then `b`. An index and not a
// name, because this graph is compiled to JSON the engine reads with no module.k7x in sight, and position is
// the one fact both documents can hold on their own.
//
// This is @studio/dsp's `crossfade()` graph, written out here: a module is a FOLDER you can copy, so it
// carries its own source rather than pointing at a shared library. packages/dsp/src/crossfade.test.ts holds
// the two to the same shape.

import type { GraphBuilder } from "@studio/dsp";

export default (g: GraphBuilder) => {
  const mix = g.param("Mix", { min: 0, max: 1, default: 0.5 });
  // Equal GAIN and not equal power: no sqrt among the primitives, so the centre dips a known ~3 dB.
  g.input(0).mul(mix.from(1)).add(g.input(1).mul(mix)).out();
};

// A module that declares its OWN ports, instead of taking the one audio input its type folder
// would have given it. That is the whole reason a crossfade was unsayable before: `audio/` means
// one in, one out, and a folder is not the right place to decide how many wires an effect takes.
//
// `mandatory: false` on `b`: wiring one side and leaving the other silent is a legitimate state,
// not a half-built chain. Drop this module into a chain on its own and it plays deck A alone.
//
// `plugin: {type: dsp}` says the sound comes from the `dsp.k7x` beside this file — one
// statement for both facts, so there is no `dsp:` field to keep in step with a plugin name.
plugin({ type: "dsp", name: "Crossfade" })
inputs([name("a").type("audio"), name("b").type("audio").mandatory(false)])
outputs([name("out").type("audio")])
params({
  // The graph's own parameter, by its display name — that is how a param finds its plugin
  // (see applyPluginParams). Centred: both decks at once, which is what makes the demo audible.
  Mix: 0.5,
})
// A two-input crossfade. Mix at 0 is deck A alone, at 1 deck B alone, at 0.5 both at half.
// (Was `docs:`. To say this on the GRAPH, wire this module into a node of `@meta/doc`.)

// A RACK instrument: a note -> audio sampler (type: "rack"), not a plugin. This module is the
// sampler and nothing more: the sounds — each a TAP, a MIDI note and the sample it fires — are
// written on the NODE that uses it (see rack-demo.k7/nodes/kit.k7x), so every node of this
// module can be a different kit. Samples live in a library's samples/ or a project's own.
type("rack")

// The Tracktion built-in 4OSC synth. It sits in instruments/, so it's a
// midi -> audio plugin with a mandatory MIDI input — both derived from the folder.
// `plugin.type` is the FORMAT: "internal" for a built-in, whose xmlTypeName goes in
// `name` (an external plugin uses type: "vst3" / "au" / … and name: its real name).
plugin({ type: "internal", name: "4osc" })
// The UI every module that extends this one draws inside its rectangle on the Chains
// graph. The extending module overrides one widget by restating it under the same id.
//
// The ranges are 4OSC's own. A built-in's params are in NATIVE units, not the 0..1
// an external plugin reports: "Filter Freq" is a 0..135 note-ish scale rather than
// Hz, and "Level" is dB. They have to be written down here — nothing reports a
// parameter's bounds at runtime, so an unranged control would be guessing.
ui({
  cols: 4,
