// A module that extends the 4OSC (instruments/fourosc) with default params. Add a
// params: {…} here to tweak it, or a synth.vstpreset beside this file for opaque state
// (a UI edit writes that automatically).
//
// A module file is a flat struct of its own attributes, with no `package` clause —
// that keeps sibling modules in this folder from colliding on `name`.
//
// Two NODES use this module — nodes/lead.k7x and nodes/pad.k7x, which
// chains.k7x names "lead" and "pad". They live in the project's flat nodes/ folder
// rather than beside this file, and reach it through `extends`; whatever you change here
// reaches both.
extends("@workspace/instruments/fourosc")
// The lead 4OSC. Two saws detuned a few cents, a slow filter sweep on the way in.
//
// TODO: automate the filter cutoff instead of leaving it static; try a sub-oscillator an
// octave down.
//
// Was `docs:`/`todos:`, read by the Docs panel. To say this ON THE GRAPH instead, add a
// node of `@meta/doc` with a `content:` and wire this module into it.
// Automation. The hand-drawn `sweep` curve rides the filter cutoff — "Filter Freq"
// has a widget in the graph, so the curve's arrow lands on it. The bipolar `wobble`
// LFO detunes osc 1; "Osc1 Tune" has no widget, so its arrow points at the module
// with the param named instead.
automations([
  param("Filter Freq").curve("@meta/curves/sweep"),
  param("Osc1 Tune").curve("@meta/curves/wobble"),
])

// "glow" — a SHADER: picture in, picture out, and an optional audio input that drives it.
//
// The folder it sits in (`_modules/shaders/`) is what says so; nothing here names a plugin,
// because there is none. What this module DOES is the GLSL under `shaders/`, one folder per
// shader, and `shader:` below picks which of them runs.
//
// `P1`..`P4` are the four knobs every shader gets, 0..1, reaching the fragment as `uP1`..`uP4`.
// What each one means is the shader's business — read the comments in its fragment.glsl.
// See apps/k7-daw-frontend/packages/song-video/docs/shaders.md.
type("shader")
shader("pulse")
params({
  P1: 0.6, // pulse: how hard the sound lifts the picture
  P2: 0.35, // pulse: vignette
  P3: 0,
  P4: 0,
})

#version 300 es
// "pulse" — the picture brightens with the sound, inside a vignette.
//
// The simplest thing that shows the audio input actually arriving: wire a lane to this node's
// `audio` port and the frame breathes with it. With nothing wired, `uAudio` is 0 and this is a
// vignette and nothing else, which is a legitimate way to use it.
precision mediump float;

in vec2 vUV;

uniform sampler2D uTex;   // the picture coming in
uniform float uAudio;     // 0..1, the wired lane's live level (-60..0 dB)
uniform float uP1;        // how hard the sound lifts the picture
uniform float uP2;        // vignette depth

out vec4 outColor;

void main() {
  vec4 c = texture(uTex, vUV);

  // Lift, never cut: at uAudio 0 this is 1.0, so silence leaves the picture exactly as it came in.
  // A shader that darkened at rest would make every lane look wrong the moment you added it.
  float lift = 1.0 + uAudio * uP1 * 2.0;

  // Squared distance from the centre, doubled so the corners reach ~1 on a square frame.
  vec2 d = vUV - 0.5;
  float vig = 1.0 - uP2 * clamp(dot(d, d) * 2.0, 0.0, 1.0);

  // Alpha is passed straight through. The layer is composited OVER whatever is under it, so
  // writing 1.0 here would make a picture-in-picture punch a hole in the lane below it.
  outColor = vec4(c.rgb * lift * vig, c.a);
}

#version 300 es
// The vertex stage every full-target pass wants: `aUnit` is the unit quad the compositor binds,
// and a pass covers the whole of what it draws into — so this maps (0,0)..(1,1) onto clip space
// and hands the fragment the same 0..1 as its texture coordinate.
//
// It is a separate file, and duplicated per shader on purpose: a shader is the PAIR, and the day
// one wants to move its geometry it needs this file to itself rather than a shared one it would
// have to fork. See apps/k7-daw-frontend/packages/song-video/docs/shaders.md.
in vec2 aUnit;
out vec2 vUV;

void main() {
  vUV = aUnit;
  gl_Position = vec4(aUnit * 2.0 - 1.0, 0.0, 1.0);
}

#version 300 es
// "ripple" — rings running out from the centre, their depth driven by the sound.
//
// The second shader in this folder, and its job is to prove the dropdown: pick it instead of
// "pulse" and the same node, the same four knobs and the same audio cable do something else.
precision mediump float;

in vec2 vUV;

uniform sampler2D uTex;    // the picture coming in
uniform float uAudio;      // 0..1, the wired lane's live level
uniform float uTime;       // seconds — the TRANSPORT's position, not a clock of the renderer's
uniform vec2 uResolution;  // the viewport in px, for the aspect correction below
uniform float uP1;         // ring depth at full level
uniform float uP2;         // how many rings across the frame
uniform float uP3;         // how fast they travel

out vec4 outColor;

void main() {
  // Aspect-corrected, or the rings are ellipses on any frame that is not square. `uResolution` is
  // the VIEWPORT's — a layer's chain runs at viewport size whatever rect the lane occupies, which
  // is what keeps an effect looking the same on a picture-in-picture as on a full-frame lane.
  vec2 d = vUV - 0.5;
  d.x *= uResolution.x / max(uResolution.y, 1.0);
  float r = length(d);

  // 2..34 rings, and 0..2 rings per second outward. Both ends of each range are useful: the
  // bottom of `uP2` is a single slow swell, the top is a fine corduroy.
  float rings = 2.0 + uP2 * 32.0;
  float wave = sin(r * rings - uTime * uP3 * 2.0);

  // The displacement is along the radius, so the rings push the picture out and pull it back
  // rather than smearing it sideways. Guarded at the exact centre, where `d / r` is 0/0.
  float amount = wave * uAudio * uP1 * 0.05;
  vec2 dir = r > 0.0001 ? d / r : vec2(0.0);
  vec2 uv = clamp(vUV + dir * amount, 0.0, 1.0);

  outColor = texture(uTex, uv);
}

#version 300 es
// The same full-target quad "pulse" uses — see the note in its vertex.glsl for why each shader
// carries its own copy rather than sharing one.
in vec2 aUnit;
out vec2 vUV;

void main() {
  vUV = aUnit;
  gl_Position = vec4(aUnit * 2.0 - 1.0, 0.0, 1.0);
}

// The panel drawn inside this node's card on the graph.
//
// The dropdown binds `@shader` and says NOTHING about its entries: which shaders exist is a fact
// about the folder, and a list written here would be a copy of a directory going stale between
// saves. The graph fills it from what the loader found — the same arrangement `@base` has.
cols(4)
rows(2)
widgets({
  pick: { type: "dropdown", col: 0, row: 0, colSpan: 4, bind: "@shader" },
  p1: { type: "knob", col: 0, row: 1, bind: "P1", min: 0, max: 1, step: 0.01 },
  p2: { type: "knob", col: 1, row: 1, bind: "P2", min: 0, max: 1, step: 0.01 },
  p3: { type: "knob", col: 2, row: 1, bind: "P3", min: 0, max: 1, step: 0.01 },
  p4: { type: "knob", col: 3, row: 1, bind: "P4", min: 0, max: 1, step: 0.01 },
})

// "iris" — a SHADER meant for a fade's STRETCH: the shot is shown inside a circle that opens with
// its presence, so the same node opens a shot in on a `fade_in` and closes one out on a `fade_out`.
//
// Wired as an ordinary lane effect it does nothing, since `uPresence` is 1 outside a fade.
// See apps/k7-daw-frontend/packages/song-video/docs/transitions.md.
type("shader")
shader("iris")
params({
  P1: 0.15, // iris: how soft the circle's edge is
  P2: 0,
  P3: 0,
  P4: 0,
})

#version 300 es
// "iris" — the shot inside a circle whose radius follows `uPresence`: closed at 0, the whole
// frame at 1. Only the ALPHA changes, which is what lets the built-in `over` mix it with the shot
// underneath — see apps/k7-daw-frontend/packages/song-video/docs/transitions.md.
precision mediump float;

in vec2 vUV;

uniform sampler2D uTex;       // the shot coming in
uniform float uPresence;      // 0..1, how much of the shot is on screen
uniform vec2 uResolution;     // the viewport, so the circle stays round on a wide frame
uniform float uP1;            // edge softness

out vec4 outColor;

void main() {
  vec4 c = texture(uTex, vUV);
  // Distance from the centre in units of the frame's HEIGHT, so a 16:9 frame does not squash the circle.
  vec2 d = (vUV - 0.5) * vec2(uResolution.x / uResolution.y, 1.0);
  float soft = max(uP1 * 0.5, 0.001);
  // The radius reaches past the corner at presence 1, edge included, so a whole shot has no rim.
  float far = length(vec2(uResolution.x / uResolution.y, 1.0) * 0.5) + soft;
  float r = uPresence * far;
  outColor = vec4(c.rgb, c.a * (1.0 - smoothstep(r - soft, r, length(d))));
}

#version 300 es
// The vertex stage every full-target pass wants: `aUnit` is the unit quad the compositor binds,
// and a pass covers the whole of what it draws into — so this maps (0,0)..(1,1) onto clip space
// and hands the fragment the same 0..1 as its texture coordinate.
//
// It is a separate file, and duplicated per shader on purpose: a shader is the PAIR, and the day
// one wants to move its geometry it needs this file to itself rather than a shared one it would
// have to fork. See apps/k7-daw-frontend/packages/song-video/docs/shaders.md.
in vec2 aUnit;
out vec2 vUV;

void main() {
  vUV = aUnit;
  gl_Position = vec4(aUnit * 2.0 - 1.0, 0.0, 1.0);
}

